<script setup>
import {ref,watch,nextTick,onMounted,onUnmounted} from 'vue';
import {notices,dismiss,pause,resume} from '../notifications.js';
const container=ref(null),target=ref(document.body);let observer;
async function sync(){const dialogs=document.querySelectorAll('dialog[open]');const desired=dialogs[dialogs.length-1] || document.body;if(target.value!==desired)target.value=desired;await nextTick();if(!container.value)return;if(notices.value.length){if(container.value.matches(':popover-open'))container.value.hidePopover();container.value.showPopover();}else if(container.value.matches(':popover-open'))container.value.hidePopover();}
watch(()=>notices.value.map(n=>n.id).join(','),sync);onMounted(()=>{sync();observer=new MutationObserver(records=>{if(records.some(r=>r.type==='attributes' || [...r.addedNodes,...r.removedNodes].some(n=>n.nodeType===1&&(n.matches?.('dialog')||n.querySelector?.('dialog')))))sync();});observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['open']});});onUnmounted(()=>observer?.disconnect());
</script>
<template><Teleport :to="target"><div ref="container" popover="manual" class="notification-stack" aria-label="操作通知"><TransitionGroup name="notification"><article v-for="notice in notices" :key="notice.id" :class="['notification-card',notice.type]" :role="notice.type==='error'?'alert':'status'" @mouseenter="pause(notice.id)" @mouseleave="resume(notice.id)"><span class="notification-indicator" aria-hidden="true">{{ notice.type==='error'?'!':notice.type==='warning'?'!':'✓' }}</span><div><strong>{{ notice.type==='error'?'操作失败':notice.type==='warning'?'运行提醒':'操作完成' }}</strong><p>{{ notice.text }}</p></div><button type="button" class="notification-dismiss" aria-label="关闭通知" @click="dismiss(notice.id)">×</button></article></TransitionGroup></div></Teleport></template>
